// Golden files in testdata/ are generated by trivy itself, so these tests
// prove the Go renderer is a drop-in replacement for `trivy convert`:
//
//	cp trivy-template.html /tmp/detail.tpl
//	trivy convert -f template -t @/tmp/detail.tpl -o testdata/report.golden.html testdata/report.json
//	trivy convert -f template -t @/tmp/detail.tpl --severity CRITICAL,HIGH -o testdata/report-critical-high.golden.html testdata/report.json
//	trivy convert -f template -t @/tmp/detail.tpl -o testdata/empty.golden.html testdata/empty.json

var timestampRe = regexp.MustCompile(`\d{4}-\d{2}-\d{2} \d{2}:\d{2}`)

func TestRenderDetailMatchesTrivyConvert(t *testing.T) {
	tests := []struct {
		name     string
		input    string
		severity string
		golden   string
	}{
		{"all severities", "testdata/report.json", "", "testdata/report.golden.html"},
		{"critical and high", "testdata/report.json", "CRITICAL,HIGH", "testdata/report-critical-high.golden.html"},
		{"no results", "testdata/empty.json", "", "testdata/empty.golden.html"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			rep, err := loadReport(tt.input)
			if err != nil {
				t.Fatal(err)
			}
			var got bytes.Buffer
			if err := renderDetail(&got, rep, parseSeverity(tt.severity)); err != nil {
				t.Fatal(err)
			}
			want, err := os.ReadFile(tt.golden)
			if err != nil {
				t.Fatal(err)
			}
			g := timestampRe.ReplaceAllString(got.String(), "TIME")
			w := timestampRe.ReplaceAllString(string(want), "TIME")
			if g != w {
				t.Errorf("output differs from %s (trivy convert)\n%s", tt.golden, firstDiff(w, g))
			}
		})
	}
}

func firstDiff(want, got string) string {
	wl, gl := strings.Split(want, "\n"), strings.Split(got, "\n")
	for i := 0; i < len(wl) || i < len(gl); i++ {
		var w, g string
		if i < len(wl) {
			w = wl[i]
		}
		if i < len(gl) {
			g = gl[i]
		}
		if w != g {
			return fmt.Sprintf("line %d:\n  want: %q\n  got:  %q", i+1, w, g)
		}
	}
	return ""
}

func TestSummary(t *testing.T) {
	rep, err := loadReport("testdata/report.json")
	if err != nil {
		t.Fatal(err)
	}
	empty, err := loadReport("testdata/empty.json")
	if err != nil {
		t.Fatal(err)
	}

	row := summarize("app_abc123", "testdata/report.json", rep, nil)
	wantCounts := map[string]int{"CRITICAL": 2, "HIGH": 2, "MEDIUM": 1, "LOW": 3, "UNKNOWN": 1}
	for s, n := range wantCounts {
		if row.Counts[s] != n {
			t.Errorf("Counts[%s] = %d, want %d", s, row.Counts[s], n)
		}
	}
	if row.Total != 9 || row.Highest != "CRITICAL" {
		t.Errorf("Total=%d Highest=%q, want 9 CRITICAL", row.Total, row.Highest)
	}
	if row.Label != "app:1.0" || row.OS != "alpine 3.19.1" || row.Digest != "0123456789ab" {
		t.Errorf("Label=%q OS=%q Digest=%q", row.Label, row.OS, row.Digest)
	}
	if row.Href != "html/app_abc123.html" {
		t.Errorf("Href = %q", row.Href)
	}

	filtered := summarize("app_abc123", "testdata/report.json", rep, parseSeverity("critical, high"))
	if filtered.Total != 4 || filtered.Counts["MEDIUM"] != 0 {
		t.Errorf("-s CRITICAL,HIGH: Total=%d Counts=%v, want 4 without MEDIUM", filtered.Total, filtered.Counts)
	}

	clean := summarize("clean_def456", "testdata/empty.json", empty, nil)
	if clean.Label != "clean.tar" || clean.OS != "-" || clean.Total != 0 || clean.Highest != "" {
		t.Errorf("clean row = %+v", clean)
	}

	var buf bytes.Buffer
	rows := map[string]summaryRow{clean.Stem: clean, row.Stem: row}
	if err := renderSummary(&buf, rows, nil); err != nil {
		t.Fatal(err)
	}
	html := buf.String()

	if strings.Contains(html, "ZgotmplZ") {
		t.Error("summary contains ZgotmplZ: CSS was escaped")
	}
	if !strings.Contains(html, "--critical:") || !strings.Contains(html, ".severity-badge.CRITICAL") {
		t.Error("summary does not include the shared detail CSS")
	}
	if i, j := strings.Index(html, "app:1.0"), strings.Index(html, "clean.tar"); i < 0 || j < 0 || i > j {
		t.Error("rows not sorted by severity (app:1.0 should come before clean.tar)")
	}
	for _, want := range []string{`href="html/app_abc123.html"`, `href="html/clean_def456.html"`, `class="severity-CRITICAL"`, ">Unknown</th>"} {
		if !strings.Contains(html, want) {
			t.Errorf("summary missing %s", want)
		}
	}

	buf.Reset()
	if err := renderSummary(&buf, map[string]summaryRow{}, parseSeverity("CRITICAL,HIGH")); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(buf.String(), "No Reports Found") || strings.Contains(buf.String(), ">Medium</th>") {
		t.Error("empty summary with -s CRITICAL,HIGH rendered wrong")
	}
}

func TestDetailCSS(t *testing.T) {
	css := string(detailCSS())
	if !strings.Contains(css, ":root") || !strings.Contains(css, "--critical") {
		t.Fatal("detailCSS did not extract the <style> block of trivy-template.html")
	}
	if strings.Contains(css, "{{") {
		t.Fatal("detailCSS contains template actions")
	}
}

func TestLoadPreviousReports(t *testing.T) {
	out := t.TempDir()
	jsonDir := filepath.Join(out, jsonSubdir)
	if err := os.MkdirAll(jsonDir, 0o755); err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile("testdata/report.json")
	if err != nil {
		t.Fatal(err)
	}
	for name, content := range map[string][]byte{
		"old_111111.json":     data,
		"current_222222.json": data,
		"broken_333333.json":  []byte("{not json"),
	} {
		if err := os.WriteFile(filepath.Join(jsonDir, name), content, 0o644); err != nil {
			t.Fatal(err)
		}
	}

	rows := map[string]summaryRow{}
	loadPreviousReports(out, []scanTarget{{Stem: "current_222222"}}, nil, rows)

	if _, ok := rows["old_111111"]; !ok || len(rows) != 1 {
		t.Fatalf("rows = %v, want only old_111111 (current is rescanned, broken is skipped)", rows)
	}
	if _, err := os.Stat(filepath.Join(out, htmlSubdir, "old_111111.html")); err != nil {
		t.Errorf("detail page for previous report not rendered: %v", err)
	}
}

func TestReportStem(t *testing.T) {
	dir := t.TempDir()
	tar := filepath.Join(dir, "My.Image.TAR.GZ")
	if err := os.WriteFile(tar, []byte("content"), 0o644); err != nil {
		t.Fatal(err)
	}
	// sha256("content") = ed7002...
	if got := reportStem(tar); got != "My.Image_ed7002" {
		t.Errorf("reportStem(tar) = %q", got)
	}
	if got := reportStem("registry.io/app:1.0"); !strings.HasPrefix(got, "app_1.0_") {
		t.Errorf("reportStem(image ref) = %q", got)
	}
}

func TestIsReportFresh(t *testing.T) {
	path := filepath.Join(t.TempDir(), "r.json")
	if isReportFresh(path, time.Time{}) {
		t.Error("missing file reported fresh")
	}
	if err := os.WriteFile(path, []byte("{}"), 0o644); err != nil {
		t.Fatal(err)
	}
	if !isReportFresh(path, time.Now().Add(-time.Hour)) {
		t.Error("report newer than DB should be fresh")
	}
	if isReportFresh(path, time.Now().Add(time.Hour)) {
		t.Error("report older than DB should be stale")
	}
}

func TestErrorClassification(t *testing.T) {
	out := []byte("2026-11-14T14:38:13+07:00\tFATAL\tFatal error\trun error: context deadline exceeded")
	if msg := trivyErrorMessage(out); !strings.HasPrefix(msg, "FATAL") {
		t.Errorf("trivyErrorMessage = %q", msg)
	}
	timeout := fmt.Errorf("%w after 10m: %s", errScanTimeout, trivyErrorMessage(out))
	if isRetryableError(timeout) {
		t.Error("scan timeout must not be retried")
	}
	if !isRetryableError(errors.New("trivy failed: database is locked")) {
		t.Error("locked DB should be retried")
	}
	if isRetryableError(errors.New("unable to initialize archive image: connection")) {
		t.Error("invalid image must not be retried")
	}
}
